import os
from typing import Any, Dict, List, Optional

import boto3


def extract_layout_elements(
    document_path: str,
    features: Optional[List[str]] = None,
    aws_region: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract OCR and layout information from a document using Amazon Textract.

    Returns a normalized structure with pages, lines, words, tables, and blocks.
    """
    if features is None:
        features = ["TABLES", "FORMS"]

    region = aws_region or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"
    textract = boto3.client("textract", region_name=region)

    with open(document_path, "rb") as f:
        document_bytes = f.read()

    response = textract.analyze_document(
        Document={"Bytes": document_bytes},
        FeatureTypes=features,
    )

    blocks = response.get("Blocks", [])
    by_id = {b.get("Id"): b for b in blocks if b.get("Id")}

    pages: Dict[int, Dict[str, Any]] = {}
    tables: List[Dict[str, Any]] = []
    lines: List[Dict[str, Any]] = []
    words: List[Dict[str, Any]] = []

    def bbox_of(block: Dict[str, Any]) -> Dict[str, Any]:
        return block.get("Geometry", {}).get("BoundingBox", {}) or {}

    def norm_block(block: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "id": block.get("Id"),
            "block_type": block.get("BlockType"),
            "text": block.get("Text"),
            "confidence": block.get("Confidence"),
            "page": block.get("Page"),
            "bbox": bbox_of(block),
        }

    for block in blocks:
        btype = block.get("BlockType")
        page_num = block.get("Page")

        if page_num is not None:
            pages.setdefault(
                page_num,
                {
                    "page_number": page_num,
                    "blocks": [],
                    "lines": [],
                    "words": [],
                    "tables": [],
                },
            )

        if btype == "LINE":
            item = norm_block(block)
            lines.append(item)
            if page_num is not None:
                pages[page_num]["lines"].append(item)
                pages[page_num]["blocks"].append(item)

        elif btype == "WORD":
            item = norm_block(block)
            words.append(item)
            if page_num is not None:
                pages[page_num]["words"].append(item)
                pages[page_num]["blocks"].append(item)

        elif btype == "TABLE":
            cells: List[Dict[str, Any]] = []
            for rel in block.get("Relationships", []) or []:
                if rel.get("Type") == "CHILD":
                    for child_id in rel.get("Ids", []) or []:
                        child = by_id.get(child_id)
                        if child and child.get("BlockType") == "CELL":
                            cell_text_parts: List[str] = []
                            for cell_rel in child.get("Relationships", []) or []:
                                if cell_rel.get("Type") == "CHILD":
                                    for word_id in cell_rel.get("Ids", []) or []:
                                        word_block = by_id.get(word_id)
                                        if word_block and word_block.get("BlockType") == "WORD":
                                            txt = word_block.get("Text")
                                            if txt:
                                                cell_text_parts.append(txt)
                            cells.append(
                                {
                                    "id": child.get("Id"),
                                    "row_index": child.get("RowIndex"),
                                    "column_index": child.get("ColumnIndex"),
                                    "row_span": child.get("RowSpan"),
                                    "column_span": child.get("ColumnSpan"),
                                    "text": " ".join(cell_text_parts).strip(),
                                    "confidence": child.get("Confidence"),
                                    "bbox": bbox_of(child),
                                }
                            )
            table_item = {
                **norm_block(block),
                "cells": cells,
            }
            tables.append(table_item)
            if page_num is not None:
                pages[page_num]["tables"].append(table_item)
                pages[page_num]["blocks"].append(table_item)

        elif btype in {"KEY_VALUE_SET", "SELECTION_ELEMENT", "CELL", "TABLE_TITLE", "TABLE_FOOTER", "LAYOUT_TEXT", "LAYOUT_TITLE", "LAYOUT_HEADER", "LAYOUT_FOOTER", "LAYOUT_SECTION_HEADER", "LAYOUT_LIST", "LAYOUT_TABLE", "LAYOUT_FIGURE", "LAYOUT_KEY_VALUE"}:
            item = norm_block(block)
            if page_num is not None:
                pages[page_num]["blocks"].append(item)

    return {
        "provider": "amazon_textract",
        "region": region,
        "document_path": document_path,
        "features": features,
        "pages": [pages[k] for k in sorted(pages.keys())],
        "lines": lines,
        "words": words,
        "tables": tables,
        "blocks": [norm_block(b) for b in blocks],
        "raw_response": response,
    }
